/** Fallback to Indonesian when a language lacks the block or the key. */
export function getPropertiJobsLabels(language: string): Record<string, string> {
  const base = dictPropertiJobs.id;
  const over = dictPropertiJobs[language];
  if (!over || language === "id") return base;
  return { ...base, ...over };
}

/**
 * Lookup a properti+jobs dictionary string with {placeholder} interpolation.
 * Fallback order: language -> id -> key itself.
 */
export function tpj(
  language: string,
  key: string,
  vars: Record<string, string | number> = {},
): string {
  const s =
    dictPropertiJobs[language]?.[key] ?? dictPropertiJobs.id[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? ""));
}
